<?php
namespace RealEstatePro\Api;use RealEstatePro\Ai\AiManager;defined('ABSPATH')||exit;
final class Rest{public function register():void{add_action('rest_api_init',function(){register_rest_route('re-pro/v1','/property/(?P<id>\\d+)', ['methods'=>'GET','permission_callback'=>'__return_true','callback'=>[$this,'property']]);register_rest_route('re-pro/v1','/property/(?P<id>\\d+)/ai',['methods'=>'POST','permission_callback'=>fn()=>is_user_logged_in(),'callback'=>[$this,'ai']]);});}public function property(\WP_REST_Request $r):\WP_REST_Response{$id=(int)$r['id'];if(get_post_type($id)!=='property')return new \WP_REST_Response(['message'=>'Not found'],404);$tier=get_user_meta(get_current_user_id(),'re_pro_customer_tier',true)?:'free';$o=['id'=>$id,'title'=>get_the_title($id),'price'=>get_post_meta($id,'price',true),'area_sqm'=>get_post_meta($id,'area_sqm',true),'thumbnail'=>get_the_post_thumbnail_url($id,'medium')];if(in_array($tier,['pro','vip'],true))foreach(['address_full','gallery_ids','video_url','virtual_tour_url','bedrooms','bathrooms','floor','year_built'] as $f)$o[$f]=get_post_meta($id,$f,true);return new \WP_REST_Response($o);}public function ai(\WP_REST_Request $r):\WP_REST_Response{try{return new \WP_REST_Response((new AiManager())->ask(get_current_user_id(),(int)$r['id'],sanitize_text_field((string)$r->get_param('question'))));}catch(\Throwable $e){return new \WP_REST_Response(['message'=>$e->getMessage()],403);}}}